import{_ as o,C as n,o as t,c as s,a2 as a,b as d,w as r,a as l,E as c,a3 as m}from"./chunks/framework.O93z6AWZ.js";const v=JSON.parse('{"title":"Topic 1.1 — Heart Failure Readmission","description":"","frontmatter":{"title":"Topic 1.1 — Heart Failure Readmission"},"headers":[],"relativePath":"en/du_an/suy_tim.md","filePath":"en/du_an/suy_tim.md"}'),h={name:"en/du_an/suy_tim.md"};function p(g,e,u,f,b,_){const i=n("Mermaid");return t(),s("div",null,[e[1]||(e[1]=a('<h1 id="topic-1-1-predicting-acute-decompensated-heart-failure-readmission-risk" tabindex="-1">Topic 1.1: Predicting Acute Decompensated Heart Failure / Readmission Risk <a class="header-anchor" href="#topic-1-1-predicting-acute-decompensated-heart-failure-readmission-risk" aria-label="Permalink to &quot;Topic 1.1: Predicting Acute Decompensated Heart Failure / Readmission Risk&quot;">​</a></h1><p><strong>Topic group:</strong> 1. Biomedical Signals &amp; Time-series · <strong>Status:</strong> ✅ Starter literature complete · ⏳ Detailed workflow/timeline follows the common template</p><div class="tip custom-block"><p class="custom-block-title">📥 Full documentation on GitHub</p><p>Raw data and detailed source code are kept <strong>Private</strong> on the department&#39;s GitHub repository (so students complete the work themselves). This page gives you the essential information to get started.</p></div><p>Read the <strong><a href="/hmyt-book/en/course_project">Management Framework &amp; Rubric</a></strong> first — this page only specifies the details for the heart-failure problem.</p><hr><h2 id="_1-problem-statement" tabindex="-1">1. Problem statement <a class="header-anchor" href="#_1-problem-statement" aria-label="Permalink to &quot;1. Problem statement&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Research question</strong></td><td>Predict the risk of acute decompensated heart failure (ADHF) or 30-day readmission from vital-sign time series or EHR data using machine learning</td></tr><tr><td><strong>Input (X)</strong></td><td>Tabular clinical features (age, EF, eGFR, serum potassium, history...) <strong>or</strong> continuous vital-sign time series (heart rate via wearable)</td></tr><tr><td><strong>Output (Y)</strong></td><td>Binary: readmission/death within a defined time window (30 days, or 21-day early warning)</td></tr><tr><td><strong>Population</strong></td><td>Heart failure patients (HFpEF/HFrEF), elderly, possibly with comorbidities (T2DM)</td></tr><tr><td><strong>Suggested dataset</strong></td><td>MIMIC-III/IV (cardiovascular patient time series extracted), or simulated data based on a public registry</td></tr><tr><td><strong>Specific challenge</strong></td><td>Irregular sampling frequency in clinical time series; early warning (24-48h ahead) has higher clinical value than late detection</td></tr></tbody></table><hr><h2 id="_2-starter-literature-4-papers" tabindex="-1">2. Starter literature (4 papers) <a class="header-anchor" href="#_2-starter-literature-4-papers" aria-label="Permalink to &quot;2. Starter literature (4 papers)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Citekey</th><th style="text-align:center;">Year</th><th>DOI</th><th>Summary</th></tr></thead><tbody><tr><td><code>wang2025machine</code></td><td style="text-align:center;">2025</td><td><a href="https://doi.org/10.3389/fcvm.2025.1673159" target="_blank" rel="noreferrer">10.3389/fcvm.2025.1673159</a></td><td>Stacking Ensemble, N=870, AUC 0.867 — 30-day readmission (T2DM+HF patients)</td></tr><tr><td><code>maesecalvo2026predicti</code></td><td style="text-align:center;">2026</td><td><a href="https://doi.org/10.1007/s11517-026-03657-2" target="_blank" rel="noreferrer">10.1007/s11517-026-03657-2</a></td><td>RF vs Logistic Regression, N~5,000 (20-year registry), AUC 0.812 vs 0.686</td></tr><tr><td><code>zhai2026explaina</code></td><td style="text-align:center;">2026</td><td><a href="https://doi.org/10.1186/s12911-026-03682-z" target="_blank" rel="noreferrer">10.1186/s12911-026-03682-z</a></td><td>XGBoost, N=1,308, internal AUC 0.968 → <strong>external AUC 0.718</strong> (a clear overfitting warning — an important lesson for students on external validation)</td></tr><tr><td><code>vanes2025circadian</code></td><td style="text-align:center;">2025</td><td><a href="https://doi.org/10.1002/ehf2.15395" target="_blank" rel="noreferrer">10.1002/ehf2.15395</a></td><td><strong>Genuine LSTM on time series</strong> of circadian heart rate (wearable), N=65, AUC~0.74, predicting ADHF 21 days ahead</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Lesson from zhai2026explaina</p><p>AUC drops sharply from 0.968 (internal) to 0.718 (external validation on eICU-CRD) — concrete evidence of overfitting risk when only evaluating internally. Teams choosing this topic <strong>must</strong> design external validation if possible, or at minimum clearly discuss this limitation when they cannot.</p></div><h3 id="prisma-diagram" tabindex="-1">PRISMA diagram <a class="header-anchor" href="#prisma-diagram" aria-label="Permalink to &quot;PRISMA diagram&quot;">​</a></h3>',12)),(t(),d(m,null,{default:r(()=>[c(i,{id:"mermaid-168",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A5%5B%22Previously%20Crossref-verified%3A%203%22%5D%20--%3E%20TOTAL_ID%0A%20%20%20%20A6%5B%22New%20WebSearch%20(filling%20the%20LSTM%20gap)%3A%201%22%5D%20--%3E%20TOTAL_ID%5B%22Total%20records%3Cbr%3EN%20%3D%204%22%5D%0A%20%20%20%20TOTAL_ID%20--%3E%20FINAL_INC%5B%22INCLUDE%20into%20Evidence%20Matrix%3Cbr%3EN%20%3D%204%20(0%20EXCLUDE)%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_3-workflow-timeline" tabindex="-1">3. Workflow &amp; Timeline <a class="header-anchor" href="#_3-workflow-timeline" aria-label="Permalink to &quot;3. Workflow &amp; Timeline&quot;">​</a></h2><p>Follow the common <strong>7-stage workflow</strong> and <strong>15-week timeline</strong> (see the full template on <a href="/hmyt-book/en/du_an/roi_loan_nhip_tim">Topic 1.2 — Arrhythmia</a>). Heart-failure-specific technical notes:</p><ul><li><strong>gd3-preprocessing:</strong> if using tabular/EHR data — handle missing values with MICE/KNN Imputer fit only on Train; if using vital-sign time series — normalize windowing, handle irregular sampling. Patient-level split is mandatory by patient ID (never let one patient appear in both Train and Test).</li><li><strong>gd4/gd5:</strong> a mandatory Logistic Regression baseline (as <code>maesecalvo2026predicti</code> did) before trying RF/XGBoost/LSTM.</li><li><strong>gd6-evaluation-xai:</strong> use SHAP for tabular models (as <code>wang2025machine</code>, <code>zhai2026explaina</code> did); if choosing the LSTM route, consider attention weights or time-series SHAP for explainability.</li><li><strong>Extension suggestion:</strong> if the team has time, try <strong>combining</strong> tabular features + time series (multimodal) — this is a gap none of the 4 starter papers have explored.</li></ul><hr><h2 id="_4-open-items-from-the-literature-report" tabindex="-1">4. Open items (from the literature report) <a class="header-anchor" href="#_4-open-items-from-the-literature-report" aria-label="Permalink to &quot;4. Open items (from the literature report)&quot;">​</a></h2><ol><li><code>comparator</code>/<code>validation_strategy</code> of <code>vanes2025circadian</code> needs the full text to complete.</li><li>Students must add ≥6 more papers to meet the ≥10-paper requirement of Rubric Milestone 1.</li></ol><div class="warning custom-block"><p class="custom-block-title">Zero-Hallucination</p><p>Every citation must match a real key in <code>.bib</code> with a DOI verified via the Crossref API. Violations are handled under Part IV.5 of the common framework.</p></div>',8))])}const k=o(h,[["render",p]]);export{v as __pageData,k as default};
